-- ==========================================================
-- AUTOMATED 10-DAY NONOGRAM PUZZLES INSERT SCRIPT FOR SUPABASE
-- Includes 5x5, 10x10, and 15x15 varied pixel-art grids
-- ==========================================================

ON CONFLICT (date_string) DO UPDATE SET
  title = EXCLUDED.title,
  width = EXCLUDED.width,
  height = EXCLUDED.height,
  solution = EXCLUDED.solution,
  row_clues = EXCLUDED.row_clues,
  col_clues = EXCLUDED.col_clues;
